var doc = app.activeDocument;
for (var i = 0; i < doc.artLayers.length; i++) {
  var l = doc.artLayers[i];
  if (l.kind == LayerKind.SMARTOBJECT) $.writeln("Smart object: " + l.name);
  if (l.kind == LayerKind.TEXT) $.writeln("Text: " + l.textItem.contents);
}

var lyr = app.activeDocument.activeLayer;
lyr.blendMode = BlendMode.OVERLAY;
lyr.opacity = 45;
lyr.visible = true;

var lyr = app.activeDocument.activeLayer;
var wasLocked = lyr.allLocked;
lyr.allLocked = false;
lyr.translate(10, 0);
lyr.allLocked = wasLocked;

app.preferences.rulerUnits = Units.PIXELS;
var doc = app.activeDocument, lyr = doc.activeLayer;
var b = lyr.bounds;
var w = b[2].value - b[0].value, h = b[3].value - b[1].value;
// centre the layer on the canvas
lyr.translate((doc.width.value - w) / 2 - b[0].value, (doc.height.value - h) / 2 - b[1].value);

var doc = app.activeDocument;
var base = doc.artLayers.getByName("product");
var tint = doc.artLayers.add();
tint.name = "tint";
tint.move(base, ElementPlacement.PLACEBEFORE);   // directly above
tint.grouped = true;                             // clip to product

var lyr = app.activeDocument.activeLayer;
try {
  lyr.applyStyle("Sunset Sky (Text)");
} catch (e) {
  alert("Load the style set first: " + e.message);
}

var lyr = app.activeDocument.activeLayer;
lyr.resize(50, 50, AnchorPosition.TOPLEFT);
lyr.rotate(-15, AnchorPosition.MIDDLECENTER);
lyr.translate(UnitValue(120, "px"), UnitValue(-40, "px"));

var doc = app.activeDocument;
var grp = doc.layerSets.add(); grp.name = "Retouch";
var l = doc.artLayers.getByName("skin");
l.move(grp, ElementPlacement.INSIDE);
grp.move(doc.layers[0], ElementPlacement.PLACEBEFORE);   // group to top

var doc = app.activeDocument;
var t = doc.artLayers.getByName("headline");
t.rasterize(RasterizeType.TEXTCONTENTS);
var merged = t.merge();   // into the layer beneath
merged.name = "headline flat";

function selectLayerById(id) {
  var ref = new ActionReference();
  ref.putIdentifier(stringIDToTypeID("layer"), id);
  var d = new ActionDescriptor();
  d.putReference(stringIDToTypeID("null"), ref);
  d.putBoolean(stringIDToTypeID("makeVisible"), false);
  executeAction(stringIDToTypeID("select"), d, DialogModes.NO);
}

app.displayDialogs = DialogModes.ERROR;
var d = app.open(new File("C:/in/a.tif"));
d.saveAs(new File("C:/out/a.jpg"), new JPEGSaveOptions(), true, Extension.LOWERCASE);
d.close(SaveOptions.DONOTSAVECHANGES);

var doc = app.activeDocument;
UnitValue.baseUnit = UnitValue(1 / doc.resolution, "in");   // px conversions now use the doc ppi
var widthPx = doc.width.as("px");
var widthCm = doc.width.as("cm");
$.writeln(widthPx + " px = " + widthCm.toFixed(2) + " cm at " + doc.resolution + " ppi");

var doc = app.activeDocument;
if (doc.bitsPerChannel == BitsPerChannelType.SIXTEEN) doc.bitsPerChannel = BitsPerChannelType.EIGHT;
if (doc.mode != DocumentMode.RGB) doc.changeMode(ChangeMode.RGB);

var doc = app.activeDocument;
doc.selection.select([[0,0],[200,0],[200,200],[0,200]]);
doc.selection.select([[150,150],[400,150],[400,400],[150,400]], SelectionType.EXTEND);
var c = new SolidColor(); c.rgb.hexValue = "FF0000";
doc.selection.stroke(c, 4, StrokeLocation.INSIDE, ColorBlendMode.NORMAL, 100, false);
doc.selection.deselect();

var doc = app.activeDocument;
doc.resizeCanvas(doc.width, UnitValue(doc.height.as("px") + 200, "px"), AnchorPosition.TOPCENTER);   // add 200 px at the bottom
if (doc.colorProfileType == ColorProfileType.NONE) doc.colorProfileName = "sRGB IEC61966-2.1";

var doc = app.activeDocument;
var l = doc.artLayers.add(); l.kind = LayerKind.TEXT;
var t = l.textItem;
t.contents = "SALE"; t.size = 96; t.font = "Impact";
t.justification = Justification.CENTER;
t.capitalization = TextCase.ALLCAPS;
t.antiAliasMethod = AntiAlias.SMOOTH;
t.warpStyle = WarpStyle.ARC; t.warpBend = 30;

// Fill selection with 50% gray via Action Manager
var d = new ActionDescriptor();
d.putEnumerated(stringIDToTypeID("using"), stringIDToTypeID("fillContents"), stringIDToTypeID("gray"));
d.putUnitDouble(stringIDToTypeID("opacity"), stringIDToTypeID("percentUnit"), 100);
d.putEnumerated(stringIDToTypeID("mode"), stringIDToTypeID("blendMode"), stringIDToTypeID("normal"));
executeAction(stringIDToTypeID("fill"), d, DialogModes.NO);

// read the active document's file path without the DOM 'unsaved' exception
var ref = new ActionReference();
ref.putProperty(stringIDToTypeID("property"), stringIDToTypeID("fileReference"));
ref.putEnumerated(stringIDToTypeID("document"), stringIDToTypeID("ordinal"), stringIDToTypeID("targetEnum"));
var d = executeActionGet(ref);
var path = d.hasKey(stringIDToTypeID("fileReference")) ? d.getPath(stringIDToTypeID("fileReference")).fsName : "(unsaved)";

// select several layers by name in one command
var ref = new ActionReference();
ref.putName(stringIDToTypeID("layer"), "a");
ref.putName(stringIDToTypeID("layer"), "b");
var d = new ActionDescriptor();
d.putReference(stringIDToTypeID("null"), ref);
d.putEnumerated(stringIDToTypeID("selectionModifier"), stringIDToTypeID("selectionModifierType"), stringIDToTypeID("addToSelection"));
executeAction(stringIDToTypeID("select"), d, DialogModes.NO);

function pt(x, y) { var p = new PathPointInfo(); p.kind = PointKind.CORNERPOINT; p.anchor = [x, y]; p.leftDirection = [x, y]; p.rightDirection = [x, y]; return p; }
var sp = new SubPathInfo();
sp.closed = true; sp.operation = ShapeOperation.SHAPEADD;
sp.entireSubPath = [pt(100,100), pt(500,100), pt(500,300), pt(100,300)];
var doc = app.activeDocument;
var path = doc.pathItems.add("box", [sp]);
path.makeSelection(0, true, SelectionType.REPLACE);
path.strokePath(ToolType.BRUSH);

// typical log output (Filter > Blur > Gaussian Blur 5 px) after tidying:
function gaussianBlur(radius) {
  var d = new ActionDescriptor();
  d.putUnitDouble(stringIDToTypeID("radius"), stringIDToTypeID("pixelsUnit"), radius);
  executeAction(stringIDToTypeID("gaussianBlur"), d, DialogModes.NO);
}

