tools.example:
#target photoshop
#include "json2.jsx"        // ES3 has no JSON - include Douglas Crockford's json2
function readText(path) { var f = new File(path); if (!f.open("r")) return ""; var s = f.read(); f.close(); return s; }
var cfg = JSON.parse(readText("C:/scripts/config.json") || "{}");
$.writeln("width = " + cfg.width);

if (!BridgeTalk.isRunning("bridge")) BridgeTalk.launch("bridge");
var bt = new BridgeTalk();
bt.target = "bridge";
bt.body = "app.document.thumbnail = new Thumbnail(new Folder('C:/in')); 'ok'";
bt.onResult = function (msg) { $.writeln("Bridge said: " + msg.body); };
bt.send(10);   // wait up to 10 s

var savedUnits = app.preferences.rulerUnits, savedDialogs = app.displayDialogs;
app.preferences.rulerUnits = Units.PIXELS;
app.displayDialogs = DialogModes.NO;
try {
  var doc = app.activeDocument;
  if (doc.activeLayer.isBackgroundLayer) doc.activeLayer.isBackgroundLayer = false;
  doc.activeLayer.applyGaussianBlur(4);
} catch (e) {
  alert("Script failed: " + e.message + "\nLine " + e.line);
} finally {
  app.preferences.rulerUnits = savedUnits;
  app.displayDialogs = savedDialogs;
}

var doc = app.activeDocument;
var o = new ExportOptionsIllustrator();
o.path = IllustratorPathType.ALLPATHS;
doc.exportDocument(new File("C:/out/" + doc.name.replace(/\.[^.]+$/, "") + "_paths.ai"), ExportType.ILLUSTRATORPATHS, o);

var o = new PDFOpenOptions();
o.usePageNumber = true; o.page = 1;
o.resolution = 150; o.mode = OpenDocumentMode.RGB; o.bitsPerChannel = BitsPerChannelType.EIGHT;
o.cropPage = CropToType.MEDIABOX; o.antiAlias = true; o.suppressWarnings = true;
var doc = app.open(new File("C:/in/brochure.pdf"), o);
